def get_tooltip_for(label: str) -> str:
    entry = TOOLTIP_DICTIONARY.get(label)
    if entry is not None:
        return entry.description
    return f"Use {label} to access this feature."


def keywords_tooltip(keywords: tuple[str, ...]) -> str:
    return f"Keywords: {', '.join(keywords)}"


def copy_hex_tooltip(hex_code: str) -> str:
    return f"Click to copy: {hex_code}"


def tooltip_search(query: str, limit: int | None = None) -> list[TooltipEntry]:
    if not query:
        return []
    words = tuple(re.findall(r"[a-z0-9]+", query.lower()))
    if not words:
        return []

    matches: list[tuple[int, TooltipEntry]] = []
    for entry in TOOLTIP_DICTIONARY.values():
        score = 0
        for word in words:
            if word in entry.search_text:
                score += 18
            elif word in entry.label.lower():
                score += 12
            elif any(word.startswith(alias) for alias in entry.keywords):
                score += 6
            else:
                score = 0
                break
        if score:
            matches.append((score, entry))

    matches.sort(key=lambda item: (-item[0], item[1].label.lower()))
    results = [entry for _, entry in matches]
    return results[:limit] if limit else results
